function solvePuzzle() {
  const table = document.getElementById("puzzle-table");
  const missingCell = table.rows[2].cells[2];
  let pairs = [];
  for (let i = 0; i < table.rows.length; i++) {
    const cells = table.rows[i].cells;
    const number = parseInt(cells[0].textContent);
    const firstDigit = Math.floor(number / 10);
    const secondDigit = number % 10;
    pairs.push([firstDigit, secondDigit]);
  }
  const missingPair = pairs[2];
