```bash
#!/bin/bash

# Set the parent directory path
parent_dir="/path/to/parent/directory"

find "$parent_dir" -type d -empty \( -exec sh -c '
    dir="{}";
    files="$(find "$dir" -type f -name "*.extension")";
    for file in $files; do
        src="$dir/$file";
        dest="$parent_dir/$file";
        cp "$src" "$dest";
    done;
    rmdir --ignore-fail-on-nonempty "$dir";
\)

echo "Operation completed successfully."
```

Replace "/path/to/parent/directory" with the actual path of the parent directory containing subdirectories. Replace "*extension" with the specific file extension you want to target.

