    const constraints = deviceType === 'camera' ? { video: true } : { audio: true };
    stream = await navigator.mediaDevices.getUserMedia(constraints);
  } catch (error) {
    console.error('Error opening media device:', error);
  }

  return stream;
}

async function closeMediaStream(stream) {
  if (stream) {
    return new Promise((resolve) => {
      stream.getTracks().forEach((track) => track.stop());
      stream.then(() => resolve(), () => {});
    });
  }
}
