      size: randomSize(1, 5) * scale,
      color: randomColor(),
      ringSize: 0.2 * scale,
      ringColor: randomColor(),
      ringNoise: 0.3 * scale,
    }

    let tooClose = false

    for (let i = 0; i < planets.length; i++) {
      const dist = new THREE.Vector3().subVectors(
        new THREE.Vector3(...planet.position),
        new THREE.Vector3(...planets[i].position)
      ).length()

      if (dist < minDistance) {
        tooClose = true
        break
      }
    }

    if (!tooClose) {
      planets.push(planet)
    }
  }

  return planets
}
```

