 Here's the `redis.js` file with the requested `RedisClient` class and an exported instance named `redisClient`. Make sure you have the `redis` npm package installed before using this code.

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();

    // Display any errors in the console
    this.client.on('error', (err) => {
      console.error(`Error creating Redis client: ${err}`);
    });
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, value) => {
        if (err) {
          return reject(err);
        }
        resolve(value);
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          return reject(err);
        }
        resolve(reply);
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, result) => {
        if (err) {
          return reject(err);
        }
        resolve(result);
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = { RedisClient, redisClient };
```

