 To identify if a given sentence in Go contains a double negative, you can follow these steps:

1. Define a slice of specific negative words.
2. Split the input sentence into words.
3. Iterate through each word in the split sentence.
4. Check if the current word is in the slice of negative words or the phrase "not" followed by a negative word.
5. Keep track of the previous word in the sentence.
6. If the current word is a negative word or "not" followed by a negative word and the previous word was also a negative word or "not," then print a message indicating that the sentence contains a double negative.

Here's an example implementation in Go:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"isn't", "am not", "are not", "aren't", "hasn't", "have not", "had not", "has not been", "have not been", "had not been", "do not", "does not", "did not", "don't"}

	sentence := "He isn't not worried about the coronavirus situation"

	words := strings.Split(sentence, " ")
	prevWord := ""
	doubleNegative := false

	for _, word := range words {
		if contains(negativeWords, word) || (prevWord != "" && contains(negativeWords, prevWord) && word == "not") {
			doubleNegative = true
			break
		}
		prevWord = word
	}

	if doubleNegative {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func contains(slice []string, str string) bool {
	for _, a := range slice {
		if a == str {
			return true
		}
	}
	return false
}
```

